from target import build_profile


def test_empty_patch_keeps_defaults():
    assert build_profile({"a": 1}, {}) == {"a": 1}


def test_patch_override():
    assert build_profile({"a": 1}, {"a": 9}) == {"a": 9}


def test_patch_adds_key():
    assert build_profile({"a": 1}, {"b": 2}) == {"a": 1, "b": 2}
